package ec.edu.monster.vistas;

import android.os.Bundle;
import android.view.View;
import android.widget.EditText;
import android.widget.ArrayAdapter;
import android.graphics.Color;
import androidx.appcompat.app.AlertDialog;
import androidx.appcompat.app.AppCompatActivity;
import ec.edu.monster.configuracion.ConfiguracionSoap;
import ec.edu.monster.controladores.BancaControlador;
import ec.edu.monster.databinding.ActivityMainBinding;
import ec.edu.monster.databinding.ItemAccountBinding;
import ec.edu.monster.modelos.Modelos.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.*;

/** Vista Android: presenta resultados; el controlador conoce el dominio y SOAP. */
public final class MainActivity extends AppCompatActivity {
 private ActivityMainBinding b; private final BancaControlador c=new BancaControlador(); private final ExecutorService pool=Executors.newSingleThreadExecutor();
 private boolean actualizandoCuentas;
 @Override public void onCreate(Bundle saved){super.onCreate(saved);b=ActivityMainBinding.inflate(getLayoutInflater());setContentView(b.getRoot());b.operationTypeSpinner.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Selecciona una operación","Depósito","Retiro"}));restaurarServidor();cargarLogo();b.loginButton.setOnClickListener(v->login());b.serverConfigButton.setOnClickListener(v->editarServidor());b.refreshButton.setOnClickListener(v->cargarCuentas());b.transferButton.setOnClickListener(v->transferir());b.historyButton.setOnClickListener(v->historial());b.operationButton.setOnClickListener(v->operacion());b.reverseButton.setOnClickListener(v->reversa());b.profileButton.setOnClickListener(v->perfil());b.loadClientsButton.setOnClickListener(v->cargarClientes());b.createAccountButton.setOnClickListener(v->crearCuenta());b.logoutButton.setOnClickListener(v->salir());}
 private void cargarLogo(){int id=getResources().getIdentifier("logo_eurekabank","drawable",getPackageName());if(id!=0){b.logo.setImageResource(id);b.logoFallback.setVisibility(View.GONE);}}
 private void restaurarServidor(){String guardada=getSharedPreferences("eurekabank",MODE_PRIVATE).getString("soap_url",null);if(guardada!=null)ConfiguracionSoap.establecerUrl(guardada);}
 private void editarServidor(){EditText input=new EditText(this);input.setSingleLine(true);input.setText(ConfiguracionSoap.urlBase());input.setSelectAllOnFocus(false);int margen=(int)(24*getResources().getDisplayMetrics().density);new AlertDialog.Builder(this).setTitle("Servidor SOAP").setMessage("Solo modifica esta dirección si cambió el servidor.").setView(input,margen,0,margen,0).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",(d,w)->{try{String url=input.getText().toString().trim();ConfiguracionSoap.establecerUrl(url);getSharedPreferences("eurekabank",MODE_PRIVATE).edit().putString("soap_url",ConfiguracionSoap.urlBase()).apply();b.loginStatus.setText("Servidor actualizado.");}catch(IllegalArgumentException e){b.loginStatus.setText(e.getMessage());}}).show();}
 private void login(){String usuario=b.userInput.getText().toString().trim(),clave=b.passwordInput.getText().toString();if(usuario.isEmpty()||clave.trim().isEmpty()){b.loginStatus.setText("Usuario y contraseña son obligatorios.");return;}b.loginStatus.setText("Conectando…");enSegundoPlano(()->{Sesion s=c.login(usuario,clave);runOnUiThread(()->{b.loginScreen.setVisibility(View.GONE);b.dashboardScreen.setVisibility(View.VISIBLE);b.welcomeText.setText("Hola, "+s.nombre);cargarCuentas();});},e->b.loginStatus.setText(limpiar(e)));}
 private void cargarCuentas(){if(actualizandoCuentas)return;actualizandoCuentas=true;enSegundoPlano(()->{List<Cuenta> cs=c.cuentas();Map<String,String> estados=c.disponibilidades();for(Cuenta cuenta:cs)cuenta.disponibilidad=estados.getOrDefault(cuenta.id,"DISPONIBLE");runOnUiThread(()->{actualizandoCuentas=false;pintarCuentas(cs);});},e->runOnUiThread(()->{actualizandoCuentas=false;b.dashboardStatus.setText(limpiar(e));}));}
 private void pintarCuentas(List<Cuenta> cs){b.accountsContainer.removeAllViews();for(Cuenta x:cs){ItemAccountBinding i=ItemAccountBinding.inflate(getLayoutInflater(),b.accountsContainer,false);i.accountState.setText("CUENTA "+x.estado+" · "+x.disponibilidad);i.accountState.setTextColor(Color.parseColor("BLOQUEADA".equals(x.disponibilidad)?"#b8394b":"#087d55"));i.accountId.setText("•••• "+ultimos(x.numero));i.accountBalance.setText(String.format(Locale.US,"$ %,.2f",x.saldo));b.accountsContainer.addView(i.getRoot());}}
 private void cargarClientes(){enSegundoPlano(()->{List<Cliente> clientes=c.clientesParaCuenta();runOnUiThread(()->{ArrayAdapter<Cliente> adaptador=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,clientes);b.clientSpinner.setAdapter(adaptador);b.createAccountButton.setEnabled(!clientes.isEmpty());b.dashboardStatus.setText(clientes.isEmpty()?"No existen clientes disponibles.":"Selecciona el titular de la nueva cuenta.");});},e->b.dashboardStatus.setText(limpiar(e)));}
 private void crearCuenta(){Cliente cliente=(Cliente)b.clientSpinner.getSelectedItem();if(cliente==null){b.dashboardStatus.setText("Primero carga y selecciona un cliente.");return;}enSegundoPlano(()->{Cuenta cuenta=c.crearCuentaParaUsuario(cliente.id);runOnUiThread(()->{b.dashboardStatus.setText("Cuenta "+cuenta.numero+" creada y asignada a "+cliente.nombre+".");cargarCuentas();});},e->b.dashboardStatus.setText(limpiar(e)));}
 private void transferir(){try{String o=cuentaValida(b.originInput.getText().toString(),"Cuenta origen"),d=cuentaValida(b.destinationInput.getText().toString(),"Cuenta destino");if(o.equals(d))throw new IllegalArgumentException("Las cuentas deben ser diferentes.");BigDecimal m=montoValido(b.amountInput.getText().toString());enSegundoPlano(()->{c.transferir(o,d,m);runOnUiThread(()->{b.originInput.setText("");b.destinationInput.setText("");b.amountInput.setText("");b.dashboardStatus.setText("Transferencia completada y auditada.");cargarCuentas();});},e->b.dashboardStatus.setText(limpiar(e)));}catch(Exception e){b.dashboardStatus.setText(e.getMessage());}}
 private void historial(){try{String id=cuentaValida(b.historyAccountInput.getText().toString(),"Número de cuenta");enSegundoPlano(()->{List<Movimiento> ms=c.movimientos(id);StringBuilder x=new StringBuilder();for(Movimiento m:ms)x.append(m.tipo).append("  ·  $ ").append(m.monto).append("\n").append(m.fecha).append("\n\n");runOnUiThread(()->b.historyText.setText(x.length()==0?"No existen movimientos.":x.toString()));},e->b.historyText.setText(limpiar(e)));}catch(IllegalArgumentException e){b.historyText.setText(e.getMessage());}}
 private void perfil(){enSegundoPlano(()->{Perfil perfil=c.perfil();runOnUiThread(()->b.profileText.setText(perfil.nombre+"\n@"+perfil.usuario+"\n"+perfil.telefono+"\nCuentas asociadas: "+perfil.cuentas.size()));},e->b.profileText.setText(limpiar(e)));}
 private void operacion(){try{String seleccion=(String)b.operationTypeSpinner.getSelectedItem();if("Selecciona una operación".equals(seleccion))throw new IllegalArgumentException("Selecciona Depósito o Retiro.");String tipo="Depósito".equals(seleccion)?"INGRESO":"RETIRO",cuenta=cuentaValida(b.operationAccountInput.getText().toString(),"Número de cuenta");BigDecimal monto=montoValido(b.operationAmountInput.getText().toString());enSegundoPlano(()->{c.movimiento(tipo,cuenta,monto);runOnUiThread(()->{b.operationTypeSpinner.setSelection(0);b.operationAccountInput.setText("");b.operationAmountInput.setText("");b.dashboardStatus.setText("Operación registrada de forma auditable.");cargarCuentas();});},e->b.dashboardStatus.setText(limpiar(e)));}catch(Exception e){b.dashboardStatus.setText(e.getMessage());}}
 private void reversa(){String id=b.reverseIdInput.getText().toString().trim();if(!id.matches("[0-9a-fA-F-]{36}")){b.dashboardStatus.setText("Ingresa un ID de transacción válido.");return;}enSegundoPlano(()->{c.reversar(id);runOnUiThread(()->{b.reverseIdInput.setText("");b.dashboardStatus.setText("Reversa registrada correctamente.");cargarCuentas();});},e->b.dashboardStatus.setText(limpiar(e)));}
 private void salir(){c.salir();b.dashboardScreen.setVisibility(View.GONE);b.loginScreen.setVisibility(View.VISIBLE);b.passwordInput.setText("");b.loginStatus.setText("");}
 private void enSegundoPlano(Tarea t,Error e){pool.execute(()->{try{t.run();}catch(Exception x){runOnUiThread(()->e.run(x));}});}
 private String cuentaValida(String valor,String etiqueta){String cuenta=valor==null?"":valor.trim();if(!cuenta.matches("\\d{10}"))throw new IllegalArgumentException(etiqueta+" debe tener 10 dígitos.");return cuenta;} private BigDecimal montoValido(String valor){try{BigDecimal monto=new BigDecimal(valor==null?"":valor.trim());if(monto.compareTo(BigDecimal.ZERO)<=0)throw new NumberFormatException();return monto;}catch(NumberFormatException e){throw new IllegalArgumentException("El monto debe ser mayor a cero.");}} private String ultimos(String x){return x.length()>8?x.substring(x.length()-8):x;} private String limpiar(Exception e){return e.getMessage()==null?"No se pudo conectar con el servidor.":e.getMessage().replaceAll("(?s)<[^>]*>","").trim();}
 @FunctionalInterface interface Tarea{void run()throws Exception;} @FunctionalInterface interface Error{void run(Exception e);}
 @Override protected void onDestroy(){pool.shutdownNow();super.onDestroy();}
}
